// 순서대로 낮은 순 -> 높은 순: Y(1) -> G(2) -> B(3) -> SC(4) -> GC(5)
const TIER_LEVELS = [
  { val: 1, code: 'Y', name: 'Yellow(교육이수)' },
  { val: 2, code: 'G', name: 'Green(검증통과)' },
  { val: 3, code: 'B', name: 'Black(지도실행)' },
  { val: 4, code: 'SC', name: 'Silver Crown(사외자격)' },
  { val: 5, code: 'GC', name: 'Gold Crown(사내강사)' },
];

function getTierValue(code?: string): number {
  if (!code) return 0;
  const c = code.toUpperCase();
  if (c === 'Y') return 1;  // Yellow(교육이수)
  if (c === 'G') return 2;  // Green(검증통과)
  if (c === 'B') return 3;  // Black(지도실행)
  if (c === 'SC') return 4; // Silver Crown(사외자격)
  if (c === 'GC') return 5; // Gold Crown(사내강사)
  return 0;
}

function getTierName(tier: number): string {
  switch (tier) {
    case 1: return 'Yellow(교육이수)';
    case 2: return 'Green(검증통과)';
    case 3: return 'Black(지도실행)';
    case 4: return 'Silver Crown(사외자격)';
    case 5: return 'Gold Crown(사내강사)';
    default: return '미취득';
  }
}

function getPureTierName(tier: number): string {
  switch (tier) {
    case 1: return 'Yellow';
    case 2: return 'Green';
    case 3: return 'Black';
    case 4: return 'Silver Crown';
    case 5: return 'Gold Crown';
    default: return '미취득';
  }
}

function getTierBadgeClass(code?: string): string {
  if (!code) return 'bg-slate-100 text-slate-400 border border-slate-200';
  const c = code.toUpperCase();
  if (c === 'Y') return 'bg-amber-50 text-amber-700 border border-amber-200 font-medium';
  if (c === 'G') return 'bg-emerald-50 text-emerald-800 border border-emerald-300 font-semibold';
  if (c === 'B') return 'bg-slate-800 text-white border border-slate-700 font-medium';
  if (c === 'SC') return 'bg-sky-50 text-sky-800 border border-sky-300 font-semibold';
  if (c === 'GC') return 'bg-purple-50 text-purple-800 border border-purple-300 font-bold';
  return 'bg-slate-100 text-slate-500 border border-slate-200';
}

