      const num = targetEmps.filter(e => getTierValue(e.badges[item.badge]) >= item.tier).length;
      const rate = denom > 0 ? (num / denom) * 100 : 0;
      return {
        ...item,
        num,
        denom,
        rate: Math.round(rate * 10) / 10,
      };
